mapper.select:
SELECT c.check_no AS checkNo, c.create_time AS createTime, c.finish_time AS finishTime, i.product_id AS productId, i.product_name AS productName, i.sku_name AS skuName, i.system_stock AS systemStock, i.actual_stock AS actualStock, i.diff_quantity AS diffQuantity FROM eb_stock_check_item i INNER JOIN eb_stock_check c ON c.id = i.check_id WHERE 1 = 1 AND i.diff_quantity != 0
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
ORDER BY c.id DESC, i.id DESC
